fn hex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("hex digits"))
        .collect()
}

/// The test data of "clan" with the separation rate `rate` per year.
fn homes_data(rate: f64) -> Data {
    let (mut calibration, genome_map) =
        common::death_files(0.02, None, common::repository_diseases());
    let mut demography = common::demography();
    common::window_fertility(&mut calibration, &mut demography, 0.25);
    demography["values"]["core:separation_rate"]["value"] = serde_json::json!(rate);
    Data::new(common::definitions_with(demography, calibration, genome_map).expect("definitions"))
        .expect("checked")
}

fn founder(years: i64, sex: Sex) -> Founder {
    Founder {
        born: SimTime::from_secs(-years * Y),
        sex,
        alleles: Vec::new(),
    }
}

/// The `Start` of both scenarios.
fn homes_start() -> Input {
    Input::Start(Start {
        world_seed: 0xff,
        founder_tag: DataId::new("test:homes").expect("valid"),
        world_params: WorldParams {
            hereditary_diseases: false,
            nutrition: Vec::new(),
        },
        founders: vec![
            founder(20, Sex::Female),
            founder(21, Sex::Female),
            founder(22, Sex::Male),
            founder(30, Sex::Male),
            founder(12, Sex::Male),
            founder(25, Sex::Female),
            founder(23, Sex::Male),
        ],
        couples: vec![Couple { woman: 0, man: 2 }, Couple { woman: 1, man: 6 }],
        capacity: None,
        pool: None,
    })
}

fn sim(n: u64) -> SimId {
    SimId::try_from(n).expect("valid")
}

struct Run {
    world: World,
    out: YearOut,
    log: Vec<LogEntry>,
    /// Whether the input of "homes" comes at its stamp.
    input: bool,
}

impl Run {
    fn start(rate: f64, input: bool) -> Run {
        let mut world = World::new(homes_data(rate));
        world.submit(homes_start()).expect("accepted");
        let log = world.take_log();
        Run {
            world,
            out: YearOut::default(),
            log,
            input,
        }
    }

    fn homes() -> Run {
        Run::start(0.01, true)
    }

    fn orphans() -> Run {
        Run::start(0.05, false)
    }

    fn advance(&mut self, until: i64) {
        self.world
            .advance_until(&mut self.out, SimTime::from_secs(until), &mut |_| false);
        self.log.extend(self.world.take_log());
    }

    /// Up to `until`, with the input at its stamp if the run passes it.
    fn play(&mut self, until: i64) {
        let clock = self.world.closed_through().as_secs();
        if self.input && clock < INPUT_STAMP && until >= INPUT_STAMP {
            self.advance(INPUT_STAMP);
            self.arrange();
        }
        self.advance(until);
    }

    fn arrange(&mut self) {
        let input = Input::ArrangePartnership(ArrangePartnership {
            woman: sim(9),
            man: sim(5),
        });
        self.world.submit(input).expect("accepted");
        self.log.extend(self.world.take_log());
    }

    fn save(&self) -> Vec<u8> {
        self.world.save(&self.out.year_hashes).expect("saves")
    }

    /// The entries from `from` on, against the reference: the bytes of each, and its JSON
    /// form where the reference gives it.
    fn assert_entries(&self, from: usize, expected: &[(&str, Option<&str>)]) {
        let entries = &self.log[from..];
        assert_eq!(entries.len(), expected.len(), "entries");
        for (entry, (bytes, json)) in entries.iter().zip(expected) {
            assert_eq!(
                postcard::to_allocvec(entry).expect("encodes"),
                hex(bytes),
                "entry {}",
                serde_json::to_string(entry).expect("json")
            );
            if let Some(json) = json {
                assert_eq!(serde_json::to_string(entry).expect("json"), *json);
            }
        }
    }

    /// Plays up to the second before `at`, then that second; its entries against the
    /// reference.
    fn second(&mut self, at: i64, expected: &[(&str, Option<&str>)]) {
        self.play(at - 1);
        let before = self.log.len();
        self.play(at);
        self.assert_entries(before, expected);
    }
}

/// The save loads and the loaded world saves the same bytes (ADR-0006 section 6): the load
/// checks of the households accept every state the rules reach.
fn assert_loads(data: &Data, bytes: &[u8]) {
    let (world, years) = World::load(bytes, data.clone()).expect("loads");
    assert_eq!(world.save(&years).expect("saves"), bytes);
}

#[test]
fn the_test_data_of_homes() {
    assert_eq!(homes_data(0.01).hash(), HOMES_DATA_HASH);
    assert_eq!(homes_data(0.05).hash(), ORPHANS_DATA_HASH);
}

/// `Start` creates the founders and pairs the couples, then forms the households: each
/// couple one (both moved out), each founder of 18 or more one of his own (moved out); the
/// boy of 12 goes by the orphan rule to the foster mother `FOSTER_RANK` draws (not moved
/// out, her as carer, her and her partner as social parents, his day of leaving home
/// planned after his move).
#[test]
fn start_gives_every_founder_a_household() {
    let run = Run::homes();
    run.assert_entries(0, &START_ENTRIES);
    assert_eq!(run.save(), hex(SAVE_AFTER_START));
    assert_loads(&homes_data(0.01), &run.save());
}

/// The separation: the man founds a household of his own and moves; the children stay with
/// the mother, who becomes the carer of each.
#[test]
fn the_man_moves_out_at_the_separation() {
    let mut run = Run::homes();
    run.second(SEPARATED_AT, &SEPARATION_ENTRIES);
    assert_eq!(run.save(), hex(SAVE_AFTER_SEPARATION));
    assert_loads(&homes_data(0.01), &run.save());
}

/// A girl of 16 paired by the input moves with her partner into a new household; her day
/// of leaving home is cancelled and she has no carer from then on.
#[test]
fn a_partnership_founds_a_household() {
    let mut run = Run::homes();
    run.advance(INPUT_STAMP);
    assert_eq!(run.save(), hex(SAVE_BEFORE_INPUT));
    let before = run.log.len();
    run.arrange();
    run.assert_entries(before, &INPUT_ENTRIES);
    assert_eq!(run.save(), hex(SAVE_AFTER_INPUT));
    assert_loads(&homes_data(0.01), &run.save());
}

/// On her drawn day sim 11 leaves home: a household of her own, after her birthday in the
/// same second.
#[test]
fn a_child_leaves_home_by_its_drawn_age() {
    let mut run = Run::homes();
    run.second(LEAVES_AT, &LEAVE_HOME_ENTRIES);
    assert_eq!(run.save(), hex(SAVE_AFTER_LEAVE_HOME));
    assert_loads(&homes_data(0.01), &run.save());
}

/// When the mother dies the father in the household takes over her dependent children:
/// no entry beyond her death, no move.
#[test]
fn the_father_takes_over_when_the_mother_dies() {
    let mut run = Run::homes();
    run.second(MOTHER_DIES_AT, &MOTHER_DIES_ENTRIES);
    assert_eq!(run.save(), hex(SAVE_AFTER_MOTHER_DIES));
    assert_loads(&homes_data(0.01), &run.save());
}

/// The whole run of "homes": the year hashes, the log and the save at its end.
#[test]
fn homes_runs_as_the_reference() {
    let mut run = Run::homes();
    run.play(END);
    assert_eq!(
        run.out
            .year_hashes
            .iter()
            .map(|y| y.hash)
            .collect::<Vec<_>>(),
        YEAR_HASHES
    );
    assert_eq!(run.log.len(), LOG_ENTRIES);
    assert_eq!(log_hash(&run.log), LOG_HASH);
    assert_eq!(run.save(), hex(SAVE_END));
    assert_loads(&homes_data(0.01), &run.save());
}

/// Her two dependent children have no fit carer when she dies: they move to their nearest
/// relative of 18 or more, their father, the elder first; he cares for them.
#[test]
fn orphans_move_to_their_nearest_relative() {
    let mut run = Run::orphans();
    run.play(MOTHER_DIES_AT - 1);
    assert_eq!(run.save(), hex(ORPHANS_SAVE_BEFORE_DEATH));
    let before = run.log.len();
    run.play(MOTHER_DIES_AT);
    run.assert_entries(before, &ORPHANS_ENTRIES);
    assert_eq!(run.save(), hex(ORPHANS_SAVE_AFTER_DEATH));
    assert_loads(&homes_data(0.05), &run.save());
    run.play(END);
    assert_eq!(
        run.out
            .year_hashes
            .iter()
            .map(|y| y.hash)
            .collect::<Vec<_>>(),
        ORPHANS_YEAR_HASHES
    );
    assert_eq!(run.log.len(), ORPHANS_LOG_ENTRIES);
    assert_eq!(log_hash(&run.log), ORPHANS_LOG_HASH);
    assert_eq!(run.save(), hex(ORPHANS_SAVE_END));
    assert_loads(&homes_data(0.05), &run.save());
}

/// Review finding: an input pairs a single mother in the second her eldest child comes of
/// age (sim 2 with sim 7, a second before the 18th birthday of sim 8). The child stays in
/// her household, of age in that second; its carer clears only when its birthday runs
/// later in it. A save right after the input loads, and the run goes on as without it.
#[test]
fn a_save_after_pairing_a_mother_as_her_child_comes_of_age_loads() {
    let born: i64 = 29_030_400;
    let stamp = born + 18 * Y - 1;
    let pair = Input::ArrangePartnership(ArrangePartnership {
        woman: sim(2),
        man: sim(7),
    });
    let mut run = Run::homes();
    run.play(stamp);
    run.world.submit(pair).expect("accepted");
    run.log.extend(run.world.take_log());
    let bytes = run.save();
    assert_eq!(bytes, hex(REVIEW_SAVE_AFTER_INPUT));
    let (loaded, years) = World::load(&bytes, homes_data(0.01)).expect("loads");
    assert_eq!(loaded.save(&years).expect("saves"), bytes);
    let mut resumed = Run {
        world: loaded,
        out: YearOut {
            census: run.out.census.clone(),
            year_hashes: years,
        },
        log: Vec::new(),
        input: false,
    };
    let before = run.log.len();
    run.play(END);
    resumed.play(END);
    assert_eq!(resumed.out.year_hashes, run.out.year_hashes);
    assert_eq!(log_hash(&resumed.log), log_hash(&run.log[before..]));
    assert_eq!(resumed.log.len(), run.log.len() - before);
    assert_eq!(resumed.save(), run.save());
}
